// Year-to-date range for cumulative CSAT
const now = new Date();
const year = now.getFullYear();
const yearStart = `${year}-01-01`;
const today = now.toISOString().split('T')[0];

// ISO week number for this measurement point
const jan1 = new Date(year, 0, 1);
const weekNum = Math.ceil(((now - jan1) / 86400000 + jan1.getDay() + 1) / 7);

return [{
  json: {
    yearStart,
    today,
    year,
    week: weekNum,
    jiraBaseUrl: 'https://YOUR_DOMAIN.atlassian.net',
    serviceDeskId: 'YOUR_SERVICE_DESK_ID',
    kpiApiUrl: 'http://backend:8000'
  }
}];

// Prepare resolved issue keys for feedback lookup
// We paginate if needed — JSM feedback is per-request
const issues = $('JQL Resolved Issue Keys').first().json.issues || [];

// Return each issue key for the next HTTP node to iterate
return issues.map(issue => ({
  json: { issueKey: issue.key }
}));

// Aggregate CSAT ratings from all feedback responses
const feedbackResults = $input.all();
const dates = $('Calculate YTD Range').first().json;
const totalResolved = ($('JQL Total Resolved YTD').first().json.issues || []).length;

const ratings = [];

for (const item of feedbackResults) {
  const feedback = item.json;
  // JSM feedback response: { rating: { value: 1-5 }, comment: "..." }
  if (feedback.rating && feedback.rating.value) {
    ratings.push(feedback.rating.value);
  }
  // Alternative structure: { rating: 1-5 }
  else if (typeof feedback.rating === 'number') {
    ratings.push(feedback.rating);
  }
}

// CSAT average (target: 4.75/5)
const avgRating = ratings.length > 0
  ? Math.round((ratings.reduce((a, b) => a + b, 0) / ratings.length) * 100) / 100
  : 0;

// Response rate (target: 10%)
const responseRate = totalResolved > 0
  ? Math.round((ratings.length / totalResolved) * 10000) / 100
  : 0;

return [
  {
    json: {
      items: [
        {
          kpi_code: 'SRV-CST',
          year: dates.year,
          month: dates.week,
          value: avgRating,
          notes: `Acumulat any ${dates.year}: ${ratings.length} respostes, mitjana ${avgRating}/5`,
          workflow_id: 'jira-sdit-weekly-csat'
        },
        {
          kpi_code: 'SRV-CSR',
          year: dates.year,
          month: dates.week,
          value: responseRate,
          notes: `${ratings.length}/${totalResolved} resolts amb feedback (${responseRate}%)`,
          workflow_id: 'jira-sdit-weekly-csat'
        }
      ],
      workflow_id: 'jira-sdit-weekly-csat'
    }
  }
];
